    #[test]
    fn a_malformed_declared_marker_is_a_config_error() {
        for bad in ["", "//\n//", "a-very-long-marker"] {
            let declared = styles(&[("zz", Some(CommentStyleDecl::Line(bad.into())))]);
            let err = resolve_comment_style(std::path::Path::new("out.zz"), &declared)
                .expect_err("malformed marker must be refused");
            assert!(matches!(err.kind, crate::pipeline::PipelineErrorKind::InvalidConfig));
        }
    }

    fn styles(
        entries: &[(&str, Option<CommentStyleDecl>)],
    ) -> BTreeMap<String, Option<CommentStyleDecl>> {
        entries
            .iter()
            .map(|(k, v)| (k.to_string(), v.clone()))
            .collect()
    }

    /// The whole path, not just the table: a Julia chunk routed
